/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["penal"]=g.BC_LEI_REVISAO["penal"]||{};g.BC_LEI_REVISAO["penal"][13]=[{"key":"cp:312","law":"cp","ref":"312","label":"Código Penal — art. 312","paragraphs":["Art. 312. Apropriar-se o funcionário público de dinheiro, valor ou qualquer outro bem móvel, público ou particular, de que tem a posse em razão do cargo, ou desviá-lo, em proveito próprio ou alheio:","Pena - reclusão, de dois a doze anos, e multa.","§ 1 º Aplica-se a mesma pena, se o funcionário público, embora não tendo a posse do dinheiro, valor ou bem, o subtrai, ou concorre para que seja subtraído, em proveito próprio ou alheio, valendo-se de facilidade que lhe proporciona a qualidade de funcionário.","Peculato culposo","§ 2 º Se o funcionário concorre culposamente para o crime de outrem:","Pena - detenção, de três meses a um ano.","§ 3 º No caso do parágrafo anterior, a reparação do dano, se precede a sentença irrecorrível, extingue a punibilidade; se lhe é posterior, reduz de metade a pena imposta."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:313","law":"cp","ref":"313","label":"Código Penal — art. 313","paragraphs":["Art. 313. Apropriar-se de dinheiro ou qualquer utilidade que, no exercício do cargo, recebeu por erro de outrem:","Pena - reclusão, de um a quatro anos, e multa.","Inserção de dados falsos em sistema de informações (Nome jurídico acrescido pela Lei nº 9.983, de 14/7/2000, publicada no DOU de 17/7/2000, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:314","law":"cp","ref":"314","label":"Código Penal — art. 314","paragraphs":["Art. 314. Extraviar livro oficial ou qualquer documento, de que tem a guarda em razão do cargo; sonegá-lo ou inutilizá-lo, total ou parcialmente:","Pena - reclusão, de um a quatro anos, se o fato não constitui crime mais grave."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:315","law":"cp","ref":"315","label":"Código Penal — art. 315","paragraphs":["Art. 315. Dar às verbas ou rendas públicas aplicação diversa da estabelecida em lei:","Pena - detenção, de um a três meses, ou multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:316","law":"cp","ref":"316","label":"Código Penal — art. 316","paragraphs":["Art. 316. Exigir, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida:","Pena - reclusão, de 2 (dois) a 12 (doze) anos, e multa. (Pena com redação dada pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","Excesso de exação","§ 1 º Se o funcionário exige tributo ou contribuição social que sabe ou deveria saber indevido, ou, quando devido, emprega na cobrança meio vexatório ou gravoso, que a lei não autoriza:","Pena - reclusão, de 3 (três) a 8 (oito) anos, e multa. (Parágrafo com redação dada pela Lei nº 8.137, de 27/12/1990)","§ 2 º Se o funcionário desvia, em proveito próprio ou de outrem, o que recebeu indevidamente para recolher aos cofres públicos:","Pena - reclusão, de dois a doze anos, e multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:317","law":"cp","ref":"317","label":"Código Penal — art. 317","paragraphs":["Art. 317. Solicitar ou receber, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida, ou aceitar promessa de tal vantagem:","Pena - reclusão, de 2 (dois) a 12 (doze) anos, e multa. (Pena com redação dada pela Lei nº 10.763, de 12/11/2003)","§ 1 º A pena é aumentada de um terço, se, em conseqüência da vantagem ou promessa, o funcionário retarda ou deixa de praticar qualquer ato de ofício ou o pratica infringindo dever funcional.","§ 2 º Se o funcionário pratica, deixa de praticar ou retarda ato de ofício, com infração de dever funcional, cedendo a pedido ou influência de outrem:","Pena - detenção, de três meses a um ano, ou multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:318","law":"cp","ref":"318","label":"Código Penal — art. 318","paragraphs":["Art. 318. Facilitar, com infração de dever funcional, a prática de contrabando ou descaminho (art. 334):","Pena - reclusão, de 3 (três) a 8 (oito) anos, e multa. (“Caput” do artigo com redação dada pela Lei nº 8.137, de 27/12/1990)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:319","law":"cp","ref":"319","label":"Código Penal — art. 319","paragraphs":["Art. 319. Retardar ou deixar de praticar, indevidamente, ato de ofício, ou praticá-lo contra disposição expressa de lei, para satisfazer interesse ou sentimento pessoal:","Pena - detenção, de três meses a um ano, e multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:320","law":"cp","ref":"320","label":"Código Penal — art. 320","paragraphs":["Art. 320. Deixar o funcionário, por indulgência, de responsabilizar subordinado que cometeu infração no exercício do cargo ou, quando lhe falte competência, não levar o fato ao conhecimento da autoridade competente:","Pena - detenção, de quinze dias a um mês, ou multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:321","law":"cp","ref":"321","label":"Código Penal — art. 321","paragraphs":["Art. 321. Patrocinar, direta ou indiretamente, interesse privado perante a administração pública, valendo-se da qualidade de funcionário:","Pena - detenção de um a três meses, ou multa.","Parágrafo único. Se o interesse é ilegítimo:","Pena - detenção de três meses a um ano, além da multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:322","law":"cp","ref":"322","label":"Código Penal — art. 322","paragraphs":["Art. 322. Praticar violência, no exercício de função ou a pretexto de exercê-la:","Pena - detenção, de seis meses a três anos, além da pena correspondente à violência."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:323","law":"cp","ref":"323","label":"Código Penal — art. 323","paragraphs":["Art. 323. Abandonar cargo público, fora dos casos permitidos em lei:","Pena - detenção, de quinze dias a um mês, ou multa.","§ 1 º Se do fato resulta prejuízo público:","Pena - detenção, de três meses a um ano, e multa.","§ 2 º Se o fato ocorre em lugar compreendido na faixa de fronteira:","Pena - detenção de um a três anos, e multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:324","law":"cp","ref":"324","label":"Código Penal — art. 324","paragraphs":["Art. 324. Entrar no exercício de função pública antes de satisfeitas as exigências legais, ou continuar a exercê-la, sem autorização, depois de saber oficialmente que foi exonerado, removido, substituído ou suspenso:","Pena - detenção, de quinze dias a um mês, ou multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:325","law":"cp","ref":"325","label":"Código Penal — art. 325","paragraphs":["Art. 325. Revelar fato de que tem ciência em razão do cargo e que deva permanecer em segredo, ou facilitar-lhe a revelação:","Pena - detenção, de seis meses a dois anos, ou multa, se o fato não constitui crime mais grave.","§ 1 º Nas mesmas penas deste artigo incorre quem:","I - permite ou facilita, mediante atribuição, fornecimento e empréstimo de senha ou qualquer outra forma, o acesso de pessoas não autorizadas a sistemas de informações ou banco de dados da Administração Pública;","II - se utiliza, indevidamente, do acesso restrito. (Parágrafo acrescido pela Lei nº 9.983, de 14/7/2000, publicada no DOU de 17/7/2000, em vigor 90 dias após a publicação)","§ 2 º Se da ação ou omissão resulta dano à Administração Pública ou a outrem:","Pena - reclusão, de 2 (dois) a 6 (seis) anos, e multa. (Parágrafo acrescido pela Lei nº 9.983, de 14/7/2000, publicada no DOU de 17/7/2000, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:326","law":"cp","ref":"326","label":"Código Penal — art. 326","paragraphs":["Art. 326. Devassar o sigilo de proposta de concorrência pública, ou proporcionar a terceiro o ensejo de devassá-lo:","Pena - detenção, de três meses um ano, e multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:327","law":"cp","ref":"327","label":"Código Penal — art. 327","paragraphs":["Art. 327. Considera-se funcionário público, para os efeitos penais, quem, embora transitoriamente ou sem remuneração, exerce cargo, emprego ou função pública.","§ 1 º Equipara-se a funcionário público quem exerce cargo, emprego ou função em entidade paraestatal, e quem trabalha para empresa prestadora de serviço contratada ou conveniada para a execução de atividade típica da Administração Pública. (Parágrafo único transformado em § 1º pela Lei nº 6.799, de 23/6/1980, e com nova redação dada pela Lei nº 9.983, de 14/7/2000, publicada no DOU de 17/7/2000, em vigor 90 dias após a publicação)","§ 2 º A pena será aumentada da terça parte quando os autores dos crimes previstos neste capítulo forem ocupantes de cargos em comissão ou de função de direção ou assessoramento de órgão da administração direta, sociedade de economia mista, empresa pública ou fundação instituída pelo poder público. (Parágrafo acrescido pela Lei nº 6.799, de 23/6/1980)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:328","law":"cp","ref":"328","label":"Código Penal — art. 328","paragraphs":["Art. 328. Usurpar o exercício de função pública:","Pena - detenção, de três meses a dois anos, e multa.","Parágrafo único. Se do fato o agente aufere vantagem:","Pena - reclusão, de dois a cinco anos, e multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:329","law":"cp","ref":"329","label":"Código Penal — art. 329","paragraphs":["Art. 329. Opor-se à execução de ato legal, mediante violência ou ameaça a funcionário competente para executá-lo ou a quem lhe esteja prestando auxílio:","Pena - detenção, de dois meses a dois anos.","§ 1 º Se o ato, em razão da resistência, não se executa:","Pena - reclusão, de um a três anos.","§ 2 º As penas deste artigo são aplicáveis sem prejuízo das correspondentes à violência."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:330","law":"cp","ref":"330","label":"Código Penal — art. 330","paragraphs":["Art. 330. Desobedecer a ordem legal de funcionário público:","Pena - detenção, de quinze dias a seis meses, e multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:331","law":"cp","ref":"331","label":"Código Penal — art. 331","paragraphs":["Art. 331. Desacatar funcionário público no exercício da função ou em razão dela:","Pena - detenção, de seis meses a dois anos, ou multa.","Tráfico de influência (Nome jurídico com redação dada pela Lei nº 9.127, de 16/11/1995)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:332","law":"cp","ref":"332","label":"Código Penal — art. 332","paragraphs":["Art. 332. Solicitar, exigir, cobrar ou obter, para si ou para outrem, vantagem ou promessa de vantagem, a pretexto de influir em ato praticado por funcionário público no exercício da função.","Pena - Reclusão, de dois a cinco anos, e multa.","Parágrafo único. A pena é aumentada da metade, se o agente alega ou insinua que a vantagem é também destinada ao funcionário. (Artigo com redação dada pela Lei nº 9.127, de 16/11/1995)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:333","law":"cp","ref":"333","label":"Código Penal — art. 333","paragraphs":["Art. 333. Oferecer ou prometer vantagem indevida a funcionário público, para determiná-lo a praticar, omitir ou retardar ato de ofício:","Pena - reclusão, de 2 (dois) a 12 (doze) anos, e multa. (Pena com redação dada pela Lei nº 10.763, de 12/11/2003)","Parágrafo único. A pena é aumentada de um terço, se, em razão da vantagem ou promessa, o funcionário retarda ou omite ato de ofício, ou o pratica infringindo dever funcional.","Descaminho (Nome jurídico com redação dada pela Lei nº 13.008, de 26/6/2014)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:334","law":"cp","ref":"334","label":"Código Penal — art. 334","paragraphs":["Art. 334. Iludir, no todo ou em parte, o pagamento de direito ou imposto devido pela entrada, pela saída ou pelo consumo de mercadoria:","Pena - reclusão, de 1 (um) a 4 (quatro) anos. (“Caput” do artigo com redação dada pela Lei nº 13.008, de 26/6/2014)","§ 1 º Incorre na mesma pena quem: (Parágrafo com redação dada pela Lei nº 13.008, de 26/6/2014)","I - pratica navegação de cabotagem, fora dos casos permitidos em lei; (Inciso acrescido pela Lei nº 13.008, de 26/6/2014)","II - pratica fato assimilado, em lei especial, a descaminho; (Inciso acrescido pela Lei nº 13.008, de 26/6/2014)","III - vende, expõe à venda, mantém em depósito ou, de qualquer forma, utiliza em proveito próprio ou alheio, no exercício de atividade comercial ou industrial, mercadoria de procedência estrangeira que introduziu clandestinamente no País ou importou fraudulentamente ou que sabe ser produto de introdução clandestina no território nacional ou de importação fraudulenta por parte de outrem; (Inciso acrescido pela Lei nº 13.008, de 26/6/2014)","IV - adquire, recebe ou oculta, em proveito próprio ou alheio, no exercício de atividade comercial ou industrial, mercadoria de procedência estrangeira, desacompanhada de documentação legal ou acompanhada de documentos que sabe serem falsos. (Inciso acrescido pela Lei nº 13.008, de 26/6/2014)","§ 2 º Equipara-se às atividades comerciais, para os efeitos deste artigo, qualquer forma de comércio irregular ou clandestino de mercadorias estrangeiras, inclusive o exercido em residências. (Parágrafo com redação dada pela Lei nº 13.008, de 26/6/2014)","§ 3 º A pena aplica-se em dobro se o crime de descaminho é praticado em transporte aéreo, marítimo ou fluvial. (Parágrafo acrescido pela Lei nº 4.729, de 14/7/1965, e com redação dada pela Lei nº 13.008, de 26/6/2014)","Contrabando (Nome jurídico acrescido pela Lei nº 13.008, de 26/6/2014)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:335","law":"cp","ref":"335","label":"Código Penal — art. 335","paragraphs":["Art. 335. Impedir, perturbar ou fraudar concorrência pública ou venda em hasta pública, promovida pela administração federal, estadual ou municipal, ou por entidade paraestatal; afastar ou procurar afastar concorrente ou licitante, por meio de violência, grave ameaça, fraude ou oferecimento de vantagem:","Pena - detenção, de seis meses a dois anos, ou multa além da pena correspondente à violência.","Parágrafo único. Incorre na mesma pena quem se abstém de concorrer ou licitar, em razão da vantagem oferecida."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:336","law":"cp","ref":"336","label":"Código Penal — art. 336","paragraphs":["Art. 336. Rasgar ou, de qualquer forma inutilizar ou conspurcar edital afixado por ordem de funcionário público; violar ou inutilizar selo ou sinal empregado, por determinação legal ou por ordem de funcionário público, para identificar ou cerrar qualquer objeto:","Pena - detenção, de um mês a um ano, ou multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337","law":"cp","ref":"337","label":"Código Penal — art. 337","paragraphs":["Art. 337. Subtrair, ou inutilizar, total ou parcialmente, livro oficial, processo ou documento confiado à custódia de funcionário, em razão de ofício, ou de particular em serviço público:","Pena - reclusão, de dois a cinco anos, se o fato não constitui crime grave.","Sonegação de contribuição previdenciária (Nome jurídico acrescido pela Lei nº 9.983, de 14/7/2000, publicada no DOU de 17/7/2000, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:338","law":"cp","ref":"338","label":"Código Penal — art. 338","paragraphs":["Art. 338. Reingressar no território nacional o estrangeiro que dele foi expulso:","Pena - reclusão, de um a quatro anos, sem prejuízo de nova expulsão após o cumprimento da pena.","Descumprimento de medidas protetivas de urgência (Nome jurídico acrescido pela Lei nº 15.280, de 5/12/2025)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:339","law":"cp","ref":"339","label":"Código Penal — art. 339","paragraphs":["Art. 339. Dar causa à instauração de inquérito policial, de procedimento investigatório criminal, de processo judicial, de processo administrativo disciplinar, de inquérito civil ou de ação de improbidade administrativa contra alguém, imputando-lhe crime, infração ético-disciplinar ou ato ímprobo de que o sabe inocente: (“Caput” do artigo com redação dada pela Lei nº 14.110, de 18/12/2020)","Pena - reclusão, de dois a oito anos, e multa.","§ 1 º A pena é aumentada de sexta parte, se o agente se serve de anonimato ou de nome suposto.","§ 2 º A pena é diminuída de metade, se a imputação é de prática de contravenção."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:340","law":"cp","ref":"340","label":"Código Penal — art. 340","paragraphs":["Art. 340. Provocar a ação de autoridade, comunicando-lhe a ocorrência de crime ou de contravenção que sabe não se ter verificado:","Pena - detenção, de um a seis meses, ou multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:341","law":"cp","ref":"341","label":"Código Penal — art. 341","paragraphs":["Art. 341. Acusar-se, perante a autoridade, de crime inexistente ou praticado por outrem:","Pena - detenção, de três meses a dois anos, ou multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:342","law":"cp","ref":"342","label":"Código Penal — art. 342","paragraphs":["Art. 342. Fazer afirmação falsa, ou negar ou calar a verdade, como testemunha, perito, contador, tradutor ou intérprete em processo judicial, ou administrativo, inquérito policial, ou em juízo arbitral: (“Caput” do artigo com redação dada pela Lei nº 10.268, de 28/8/2001)","Pena - reclusão, de 2 (dois) a 4 (quatro) anos, e multa. (Pena com redação dada pela Lei nº 12.850, de 2/8/2013, publicada na Edição Extra do DOU de 5/8/2013, em vigor 45 dias após a publicação)","§ 1 º As penas aumentam-se de um sexto a um terço, se o crime é praticado mediante suborno ou se cometido com o fim de obter prova destinada a produzir efeito em processo penal, ou em processo civil em que for parte entidade da administração pública direta ou indireta. (Parágrafo com redação dada pela Lei nº 10.268, de 28/8/2001)","§ 2 º O fato deixa de ser punível se, antes da sentença no processo em que ocorreu o ilícito, o agente se retrata ou declara a verdade. (Parágrafo com redação dada pela Lei nº 10.268, de 28/8/2001)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:343","law":"cp","ref":"343","label":"Código Penal — art. 343","paragraphs":["Art. 343. Dar, oferecer ou prometer dinheiro ou qualquer outra vantagem a testemunha, perito, contador, tradutor ou intérprete, para fazer afirmação falsa, negar ou calar a verdade em depoimento, perícia, cálculos, tradução ou interpretação:","Pena - reclusão, de três a quatro anos, e multa.","Parágrafo único. As penas aumentam-se de um sexto a um terço, se o crime é cometido com o fim de obter prova destinada a produzir efeito em processo penal ou em processo civil em que for parte entidade da administração pública direta ou indireta. (Artigo com redação dada pela Lei nº 10.268, de 28/8/2001)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:344","law":"cp","ref":"344","label":"Código Penal — art. 344","paragraphs":["Art. 344. Usar de violência ou grave ameaça, com o fim de favorecer interesse próprio ou alheio, contra autoridade, parte, ou qualquer outra pessoa que funciona ou é chamada a intervir em processo judicial, policial ou administrativo, ou em juízo arbitral:","Pena - reclusão, de um a quatro anos, e multa, além da pena correspondente à violência.","Parágrafo único. A pena aumenta-se de 1/3 (um terço) até a metade se o processo envolver crime contra a dignidade sexual. (Parágrafo único acrescido pela Lei nº 14.245, de 22/11/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:345","law":"cp","ref":"345","label":"Código Penal — art. 345","paragraphs":["Art. 345. Fazer justiça pelas próprias mãos, para satisfazer pretensão, embora legítima, salvo quando a lei o permite:","Pena - detenção, de quinze dias a um mês, ou multa, além da pena correspondente à violência.","Parágrafo único. Se não há emprego de violência, somente se procede mediante queixa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:346","law":"cp","ref":"346","label":"Código Penal — art. 346","paragraphs":["Art. 346. Tirar, suprimir, destruir ou danificar coisa própria, que se acha em poder de terceiro por determinação judicial ou convenção:","Pena - detenção, de seis meses a dois anos, e multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:347","law":"cp","ref":"347","label":"Código Penal — art. 347","paragraphs":["Art. 347. Inovar artificiosamente, na pendência de processo civil ou administrativo, o estado de lugar, de coisa ou de pessoa, com o fim de induzir a erro o juiz ou o perito:","Pena - detenção, de três meses a dois anos, e multa.","Parágrafo único. Se a inovação se destina a produzir efeito em processo penal, ainda que não iniciado, as penas aplicam-se em dobro."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:348","law":"cp","ref":"348","label":"Código Penal — art. 348","paragraphs":["Art. 348. Auxiliar a subtrair-se à ação de autoridade pública autor de crime a que é cominada pena de reclusão:","Pena - detenção, de um a seis meses, e multa.","§ 1 º Se ao crime não é cominada pena de reclusão:","Pena - detenção, de quinze dias a três meses, e multa.","§ 2 º Se quem presta o auxílio é ascendente, descendente, cônjuge ou irmão do criminoso, fica isento de pena."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:349","law":"cp","ref":"349","label":"Código Penal — art. 349","paragraphs":["Art. 349. Prestar a criminoso, fora dos casos de co-autoria ou de receptação, auxílio destinado a tornar seguro o proveito do crime:","Pena - detenção, de um a seis meses, e multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:350","law":"cp","ref":"350","label":"Código Penal — art. 350","paragraphs":["Art. 350. (Revogado pela Lei nº 13.869, de 5/9/2019, publicada no DOU Edição Extra de 5/9/2019, em vigor 120 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:351","law":"cp","ref":"351","label":"Código Penal — art. 351","paragraphs":["Art. 351. Promover ou facilitar a fuga de pessoa legalmente presa ou submetida a medida de segurança detentiva:","Pena - detenção, de seis meses a dois anos.","§ 1 º Se o crime é praticado à mão armada, ou por mais de uma pessoa, ou mediante arrombamento, a pena é de reclusão, de dois a seis anos.","§ 2 º Se há emprego de violência contra pessoa, aplica-se também a pena correspondente à violência.","§ 3 º A pena é de reclusão, de um a quatro anos, se o crime é praticado por pessoa sob cuja custódia ou guarda está o preso ou o internado.","§ 4 º No caso de culpa do funcionário incumbido da custódia ou guarda, aplica-se a pena de detenção, de três meses a um ano, ou multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:352","law":"cp","ref":"352","label":"Código Penal — art. 352","paragraphs":["Art. 352. Evadir-se ou tentar evadir-se o preso ou o indivíduo submetido a medida de segurança detentiva, usando de violência contra a pessoa:","Pena - detenção de três meses a um ano, além da pena correspondente à violência."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:353","law":"cp","ref":"353","label":"Código Penal — art. 353","paragraphs":["Art. 353. Arrebatar preso, afim de maltratá-lo, do poder de quem o tenha sob custódia ou guarda:","Pena - reclusão, de um a quatro anos, além da pena correspondente à violência."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:354","law":"cp","ref":"354","label":"Código Penal — art. 354","paragraphs":["Art. 354. Amotinarem-se presos, perturbando a ordem ou disciplina da prisão:","Pena - detenção, de seis meses a dois anos, além da pena correspondente à violência."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:355","law":"cp","ref":"355","label":"Código Penal — art. 355","paragraphs":["Art. 355. Trair, na qualidade de advogado ou procurador, o dever profissional, prejudicando interesse, cujo patrocínio, em juízo, lhe é confiado:","Pena - detenção, de seis meses a três anos e multa.","Patrocínio simultâneo ou tergiversação","Parágrafo único. Incorre na pena deste artigo o advogado ou procurador judicial que defende na mesma causa, simultânea ou sucessivamente, partes contrárias."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:356","law":"cp","ref":"356","label":"Código Penal — art. 356","paragraphs":["Art. 356. Inutilizar, total ou parcialmente, ou deixar de restituir autos, documento ou objeto de valor probatório, que recebeu na qualidade de advogado ou procurador:","Pena - detenção, de seis meses a três anos, e multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:357","law":"cp","ref":"357","label":"Código Penal — art. 357","paragraphs":["Art. 357. Solicitar ou receber dinheiro ou qualquer outra utilidade, a pretexto de influir em juiz, jurado, órgão do ministério público, funcionário de justiça, perito, tradutor, intérprete ou testemunha:","Pena - reclusão, de um a cinco anos, e multa.","Parágrafo único. As penas aumentam-se de um terço, se o agente alega ou insinua que o dinheiro ou utilidade também se destina a qualquer das pessoas referidas neste artigo."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:358","law":"cp","ref":"358","label":"Código Penal — art. 358","paragraphs":["Art. 358. Impedir, perturbar ou fraudar arrematação judicial; afastar ou procurar afastar concorrente ou licitante, por meio de violência, grave ameaça, fraude ou oferecimento de vantagem:","Pena - detenção de dois meses a um ano, ou multa, além da pena correspondente à violência."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359","law":"cp","ref":"359","label":"Código Penal — art. 359","paragraphs":["Art. 359. Exercer função, atividade, direito, autoridade ou múnus, de que foi suspenso ou privado por decisão judicial:","Pena - detenção, de três meses a dois anos, ou multa."],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:313-A","law":"cp","ref":"313-A","label":"Código Penal — art. 313-A","paragraphs":["Art. 313-A. Inserir ou facilitar, o funcionário autorizado, a inserção de dados falsos, alterar ou excluir indevidamente dados corretos nos sistemas informatizados ou bancos de dados da Administração Pública com o fim de obter vantagem indevida para si ou para outrem ou para causar dano;","Pena - reclusão, de 2 (dois) a 12 (doze) anos, e multa. (Artigo acrescido pela Lei nº 9.983, de 14/7/2000, publicada no DOU de 17/7/2000, em vigor 90 dias após a publicação)","Modificação ou alteração não autorizada de sistema de informações (Nome jurídico acrescido pela Lei nº 9.983, de 14/7/2000, publicada no DOU de 17/7/2000, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:313-B","law":"cp","ref":"313-B","label":"Código Penal — art. 313-B","paragraphs":["Art. 313-B. Modificar ou alterar, o funcionário, sistema de informações ou programa de informática sem autorização ou solicitação de autoridade competente:","Pena - detenção, de 3 (três) meses a 2 (dois) anos, e multa.","Parágrafo único. As penas são aumentadas de um terço até a metade se da modificação ou alteração resulta dano para a Administração Pública ou para o administrado. (Artigo acrescido pela Lei nº 9.983, de 14/7/2000, publicada no DOU de 17/7/2000, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:319-A","law":"cp","ref":"319-A","label":"Código Penal — art. 319-A","paragraphs":["Art. 319-A. Deixar o Diretor de Penitenciária e/ou agente público, de cumprir seu dever de vedar ao preso o acesso a aparelho telefônico, de rádio ou similar, que permita a comunicação com outros presos ou com o ambiente externo:","Pena: detenção, de 3 (três) meses a 1 (um) ano. (Artigo acrescido pela Lei nº 11.466, de 28/3/2007)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:334-A","law":"cp","ref":"334-A","label":"Código Penal — art. 334-A","paragraphs":["Art. 334-A. Importar ou exportar mercadoria proibida:","Pena - reclusão, de 2 (dois) a 5 (cinco) anos.","§ 1 º Incorre na mesma pena quem:","I - pratica fato assimilado, em lei especial, a contrabando;","II - importa ou exporta clandestinamente mercadoria que dependa de registro, análise ou autorização de órgão público competente;","III - reinsere no território nacional mercadoria brasileira destinada à exportação;","IV - vende, expõe à venda, mantém em depósito ou, de qualquer forma, utiliza em proveito próprio ou alheio, no exercício de atividade comercial ou industrial, mercadoria proibida pela lei brasileira;","V - adquire, recebe ou oculta, em proveito próprio ou alheio, no exercício de atividade comercial ou industrial, mercadoria proibida pela lei brasileira.","§ 2 º Equipara-se às atividades comerciais, para os efeitos deste artigo, qualquer forma de comércio irregular ou clandestino de mercadorias estrangeiras, inclusive o exercido em residências.","§ 3 º A pena aplica-se em dobro se o crime de contrabando é praticado em transporte aéreo, marítimo ou fluvial. (Artigo acrescido pela Lei nº 13.008, de 26/6/2014)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-A","law":"cp","ref":"337-A","label":"Código Penal — art. 337-A","paragraphs":["Art. 337-A. Suprimir ou reduzir contribuição social previdenciária e qualquer acessório, mediante as seguintes condutas:","I - omitir de folha de pagamento da empresa ou de documento de informações previsto pela legislação previdenciária segurados empregado, empresário, trabalhador avulso ou trabalhador autônomo ou a este equiparado que lhe prestem serviços;","II - deixar de lançar mensalmente nos títulos próprios da contabilidade da empresa as quantias descontadas dos segurados ou as devidas pelo empregador ou pelo tomador de serviços;","III - omitir, total ou parcialmente, receitas ou lucros auferidos, remunerações pagas ou creditadas e demais fatos geradores de contribuições sociais previdenciárias:","Pena - reclusão, de 2 (dois) a 5 (cinco) anos, e multa.","§ 1 º É extinta a punibilidade se o agente, espontaneamente, declara e confessa as contribuições, importâncias ou valores e presta as informações devidas à previdência social, na forma definida em lei ou regulamento, antes do início da ação fiscal.","§ 2 º É facultado ao juiz deixar de aplicar a pena ou aplicar somente a de multa se o agente for primário e de bons antecedentes, desde que:","I - (VETADO)","II - o valor das contribuições devidas, inclusive acessórios, seja igual ou inferior àquele estabelecido pela previdência social administrativamente, como sendo o mínimo para o ajuizamento de suas execuções fiscais.","§ 3 º Se o empregador não é pessoa jurídica e sua folha de pagamento mensal não ultrapassa R$ 1.510,00 (um mil, quinhentos e dez reais), o juiz poderá reduzir a pena de um terço até a metade ou aplicar apenas a de multa.","§ 4 º O valor a que se refere o parágrafo anterior será reajustado nas mesmas datas e nos mesmos índices do reajuste dos benefícios da previdência social. (Artigo acrescido pela Lei nº 9.983, de 14/7/2000, publicada no DOU de 17/7/2000, em vigor 90 dias após a publicação)","§ 5º A extinção de punibilidade de que trata o § 1º deste artigo não se aplica ao agente declarado devedor contumaz em decisão administrativa definitiva e inscrito no Cadastro Informativo dos créditos não quitados do setor público federal (Cadin), previsto na Lei nº 10.522, de 19 de julho de 2002. (Parágrafo acrescido pela Lei Complementar nº 225, de 8/1/2026)","§ 6º O fato de o agente deixar de ser considerado devedor contumaz não afasta o disposto no § 5º deste artigo em relação aos atos praticados no período em que era assim considerado. (Parágrafo acrescido pela Lei Complementar nº 225, de 8/1/2026)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-B","law":"cp","ref":"337-B","label":"Código Penal — art. 337-B","paragraphs":["Art. 337-B. Prometer, oferecer ou dar, direta ou indiretamente, vantagem indevida a funcionário público estrangeiro, ou a terceira pessoa, para determiná-lo a praticar, omitir ou retardar ato de ofício relacionado à transação comercial internacional:","Pena - reclusão, de 1 (um) a 8 (oito) anos, e multa.","Parágrafo único. A pena é aumentada de 1/3 (um terço), se, em razão da vantagem ou promessa, o funcionário público estrangeiro retarda ou omite o ato de ofício, ou o pratica infringindo dever funcional. (Artigo acrescido pela Lei nº 10.467, de 11/6/2002)","Tráfico de influência em transação comercial internacional (Nome jurídico acrescido pela Lei nº 10.467, de 11/6/2002)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-C","law":"cp","ref":"337-C","label":"Código Penal — art. 337-C","paragraphs":["Art. 337-C. Solicitar, exigir, cobrar ou obter, para si ou para outrem, direta ou indiretamente, vantagem ou promessa de vantagem a pretexto de influir em ato praticado por funcionário público estrangeiro no exercício de suas funções, relacionado a transação comercial internacional:","Pena - reclusão, de 2 (dois) a 5 (cinco) anos, e multa.","Parágrafo único. A pena é aumentada da metade, se o agente alega ou insinua que a vantagem é também destinada a funcionário estrangeiro. (Artigo acrescido pela Lei nº 10.467, de 11/6/2002)","Funcionário público estrangeiro (Nome jurídico acrescido pela Lei nº 10.467, de 11/6/2002)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-D","law":"cp","ref":"337-D","label":"Código Penal — art. 337-D","paragraphs":["Art. 337-D. Considera-se funcionário público estrangeiro, para os efeitos penais, quem, ainda que transitoriamente ou sem remuneração, exerce cargo, emprego ou função pública em entidades estatais ou em representações diplomáticas de país estrangeiro.","Parágrafo único. Equipara-se a funcionário público estrangeiro quem exerce cargo, emprego ou função em empresas controladas, diretamente ou indiretamente, pelo Poder Público de país estrangeiro ou em organizações públicas internacionais. (Artigo acrescido pela Lei nº 10.467, de 11/6/2002)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-E","law":"cp","ref":"337-E","label":"Código Penal — art. 337-E","paragraphs":["Art. 337-E. Admitir, possibilitar ou dar causa à contratação direta fora das hipóteses previstas em lei:","Pena - reclusão, de 4 (quatro) a 8 (oito) anos, e multa. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-F","law":"cp","ref":"337-F","label":"Código Penal — art. 337-F","paragraphs":["Art. 337-F. Frustrar ou fraudar, com o intuito de obter para si ou para outrem vantagem decorrente da adjudicação do objeto da licitação, o caráter competitivo do processo licitatório:","Pena - reclusão, de 4 (quatro) anos a 8 (oito) anos, e multa. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-G","law":"cp","ref":"337-G","label":"Código Penal — art. 337-G","paragraphs":["Art. 337-G. Patrocinar, direta ou indiretamente, interesse privado perante a Administração Pública, dando causa à instauração de licitação ou à celebração de contrato cuja invalidação vier a ser decretada pelo Poder Judiciário:","Pena - reclusão, de 6 (seis) meses a 3 (três) anos, e multa. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-H","law":"cp","ref":"337-H","label":"Código Penal — art. 337-H","paragraphs":["Art. 337-H. Admitir, possibilitar ou dar causa a qualquer modificação ou vantagem, inclusive prorrogação contratual, em favor do contratado, durante a execução dos contratos celebrados com a Administração Pública, sem autorização em lei, no edital da licitação ou nos respectivos instrumentos contratuais, ou, ainda, pagar fatura com preterição da ordem cronológica de sua exigibilidade:","Pena - reclusão, de 4 (quatro) anos a 8 (oito) anos, e multa. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-I","law":"cp","ref":"337-I","label":"Código Penal — art. 337-I","paragraphs":["Art. 337-I. Impedir, perturbar ou fraudar a realização de qualquer ato de processo licitatório:","Pena - detenção, de 6 (seis) meses a 3 (três) anos, e multa. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-J","law":"cp","ref":"337-J","label":"Código Penal — art. 337-J","paragraphs":["Art. 337-J. Devassar o sigilo de proposta apresentada em processo licitatório ou proporcionar a terceiro o ensejo de devassá-lo:","Pena - detenção, de 2 (dois) anos a 3 (três) anos, e multa. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-K","law":"cp","ref":"337-K","label":"Código Penal — art. 337-K","paragraphs":["Art. 337-K. Afastar ou tentar afastar licitante por meio de violência, grave ameaça, fraude ou oferecimento de vantagem de qualquer tipo:","Pena - reclusão, de 3 (três) anos a 5 (cinco) anos, e multa, além da pena correspondente à violência. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)","Parágrafo único. Incorre na mesma pena quem se abstém ou desiste de licitar em razão de vantagem oferecida. (Parágrafo único acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-L","law":"cp","ref":"337-L","label":"Código Penal — art. 337-L","paragraphs":["Art. 337-L. Fraudar, em prejuízo da Administração Pública, licitação ou contrato dela decorrente, mediante:","I - entrega de mercadoria ou prestação de serviços com qualidade ou em quantidade diversas das previstas no edital ou nos instrumentos contratuais;","II - fornecimento, como verdadeira ou perfeita, de mercadoria falsificada, deteriorada, inservível para consumo ou com prazo de validade vencido;","III - entrega de uma mercadoria por outra;","IV - alteração da substância, qualidade ou quantidade da mercadoria ou do serviço fornecido;","V - qualquer meio fraudulento que torne injustamente mais onerosa para a Administração Pública a proposta ou a execução do contrato:","Pena - reclusão, de 4 (quatro) anos a 8 (oito) anos, e multa. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-M","law":"cp","ref":"337-M","label":"Código Penal — art. 337-M","paragraphs":["Art. 337-M. Admitir à licitação empresa ou profissional declarado inidôneo:","Pena - reclusão, de 1 (um) ano a 3 (três) anos, e multa.","§ 1 º Celebrar contrato com empresa ou profissional declarado inidôneo:","Pena - reclusão, de 3 (três) anos a 6 (seis) anos, e multa.","§ 2 º Incide na mesma pena do caput deste artigo aquele que, declarado inidôneo, venha a participar de licitação e, na mesma pena do § 1º deste artigo, aquele que, declarado inidôneo, venha a contratar com a Administração Pública. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-N","law":"cp","ref":"337-N","label":"Código Penal — art. 337-N","paragraphs":["Art. 337-N. Obstar, impedir ou dificultar injustamente a inscrição de qualquer interessado nos registros cadastrais ou promover indevidamente a alteração, a suspensão ou o cancelamento de registro do inscrito:","Pena - reclusão, de 6 (seis) meses a 2 (dois) anos, e multa. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-O","law":"cp","ref":"337-O","label":"Código Penal — art. 337-O","paragraphs":["Art. 337-O. Omitir, modificar ou entregar à Administração Pública levantamento cadastral ou condição de contorno em relevante dissonância com a realidade, em frustração ao caráter competitivo da licitação ou em detrimento da seleção da proposta mais vantajosa para a Administração Pública, em contratação para a elaboração de projeto básico, projeto executivo ou anteprojeto, em diálogo competitivo ou em procedimento de manifestação de interesse:","Pena - reclusão, de 6 (seis) meses a 3 (três) anos, e multa.","§ 1 º Consideram-se condição de contorno as informações e os levantamentos suficientes e necessários para a definição da solução de projeto e dos respectivos preços pelo licitante, incluídos sondagens, topografia, estudos de demanda, condições ambientais e demais elementos ambientais impactantes, considerados requisitos mínimos ou obrigatórios em normas técnicas que orientam a elaboração de projetos.","§ 2 º Se o crime é praticado com o fim de obter benefício, direto ou indireto, próprio ou de outrem, aplica-se em dobro a pena prevista no caput deste artigo. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:337-P","law":"cp","ref":"337-P","label":"Código Penal — art. 337-P","paragraphs":["Art. 337-P. A pena de multa cominada aos crimes previstos neste Capítulo seguirá a metodologia de cálculo prevista neste Código e não poderá ser inferior a 2% (dois por cento) do valor do contrato licitado ou celebrado com contratação direta. (Artigo acrescido pela Lei nº 14.133, de 1º/4/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:338-A","law":"cp","ref":"338-A","label":"Código Penal — art. 338-A","paragraphs":["Art. 338-A. Descumprir decisão judicial que defere medidas protetivas de urgência:","Pena - reclusão, de 2 (dois) a 5 (cinco) anos, e multa.","§ 1º A configuração do crime independe da competência civil ou criminal do juiz que deferiu as medidas.","§ 2º Na hipótese de prisão em flagrante, apenas a autoridade judicial pode conceder fiança.","§ 3º O disposto neste artigo não exclui a aplicação de outras sanções cabíveis. (Artigo acrescido pela Lei nº 15.280, de 5/12/2025)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:349-A","law":"cp","ref":"349-A","label":"Código Penal — art. 349-A","paragraphs":["Art. 349-A. Ingressar, promover, intermediar, auxiliar ou facilitar a entrada de aparelho telefônico de comunicação móvel, de rádio ou similar, sem autorização legal, em estabelecimento prisional.","Pena: detenção, de 3 (três) meses a 1 (um) ano. (Artigo acrescido pela Lei nº 12.012, de 6/8/2009)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-A","law":"cp","ref":"359-A","label":"Código Penal — art. 359-A","paragraphs":["Art. 359-A. Ordenar, autorizar ou realizar operação de crédito, interno ou externo, sem prévia autorização legislativa:","Pena - reclusão, de 1 (um) a 2 (dois) anos.","Parágrafo único. Incide na mesma pena quem ordena, autoriza ou realiza operação de crédito, interno ou externo:","I - com inobservância de limite, condição ou montante estabelecido em lei ou em resolução do Senado Federal;","II - quando o montante da dívida consolidada ultrapassa o limite máximo autorizado por lei. (Artigo acrescido pela Lei nº 10.028, de 19/10/2000)","Inscrição de despesas não empenhadas em restos a pagar (Nome jurídico acrescido pela Lei nº 10.028, de 19/10/2000)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-B","law":"cp","ref":"359-B","label":"Código Penal — art. 359-B","paragraphs":["Art. 359-B. Ordenar ou autorizar a inscrição em restos a pagar, de despesa que não tenha sido previamente empenhada ou que exceda limite estabelecido em lei:","Pena - detenção, de 6 (seis) meses a 2 (dois) anos. (Artigo acrescido pela Lei nº 10.028, de 19/10/2000)","Assunção de obrigação no último ano do mandato ou legislatura (Nome jurídico acrescido pela Lei nº 10.028, de 19/10/2000)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-C","law":"cp","ref":"359-C","label":"Código Penal — art. 359-C","paragraphs":["Art. 359-C. Ordenar ou autorizar a assunção de obrigação, nos dois últimos quadrimestres do último ano do mandato ou legislatura, cuja despesa não possa ser paga no mesmo exercício financeiro ou, caso reste parcela a ser paga no exercício seguinte, que não tenha contrapartida suficiente de disponibilidade de caixa:","Pena - reclusão, de 1 (um) a 4 (quatro) anos. (Artigo acrescido pela Lei nº 10.028, de 19/10/2000)","Ordenação de despesa não autorizada (Nome jurídico acrescido pela Lei nº 10.028, de 19/10/2000)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-D","law":"cp","ref":"359-D","label":"Código Penal — art. 359-D","paragraphs":["Art. 359-D. Ordenar despesa não autorizada por lei:","Pena - reclusão, de 1 (um) a 4 (quatro) anos. (Artigo acrescido pela Lei nº 10.028, de 19/10/2000)","Prestação de garantia graciosa (Nome jurídico acrescido pela Lei nº 10.028, de 19/10/2000)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-E","law":"cp","ref":"359-E","label":"Código Penal — art. 359-E","paragraphs":["Art. 359-E. Prestar garantia em operação de crédito sem que tenha sido constituída contragarantia em valor igual ou superior ao valor da garantia prestada, na forma da lei:","Pena - detenção, de 3(três) meses a 1 (um) ano. (Artigo acrescido pela Lei nº 10.028, de 19/10/2000)","Não cancelamento de restos a pagar (Nome jurídico acrescido pela Lei nº 10.028, de 19/10/2000)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-F","law":"cp","ref":"359-F","label":"Código Penal — art. 359-F","paragraphs":["Art. 359-F. Deixar de ordenar, de autorizar ou de promover o cancelamento do montante de restos a pagar inscrito em valor superior ao permitido em lei:","Pena - detenção, de 6 (seis) meses a 2 (dois) anos. (Artigo acrescido pela Lei nº 10.028, de 19/10/2000)","Aumento de despesa total com pessoal no último ano do mandato ou legislatura (Nome jurídico acrescido pela Lei nº 10.028, de 19/10/2000)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-G","law":"cp","ref":"359-G","label":"Código Penal — art. 359-G","paragraphs":["Art. 359-G. Ordenar, autorizar ou executar ato que acarrete aumento de despesa total com pessoal, nos cento e oitenta dias anteriores ao final do mandato ou da legislatura:","Pena - reclusão, de 1 (um) a 4 (quatro) anos. (Artigo acrescido pela Lei nº 10.028, de 19/10/2000)","Oferta pública ou colocação de títulos no mercado (Nome jurídico acrescido pela Lei nº 10.028, de 19/10/2000)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-H","law":"cp","ref":"359-H","label":"Código Penal — art. 359-H","paragraphs":["Art. 359-H. Ordenar, autorizar ou promover a oferta pública ou a colocação no mercado financeiro de títulos da dívida pública sem que tenham sido criados por lei ou sem que estejam registrados em sistema centralizado de liquidação e de custódia:","Pena - reclusão, de 1 (um) a 4 (quatro) anos. (Artigo acrescido pela Lei nº 10.028, de 19/10/2000)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-I","law":"cp","ref":"359-I","label":"Código Penal — art. 359-I","paragraphs":["Art. 359-I. Negociar com governo ou grupo estrangeiro, ou seus agentes, com o fim de provocar atos típicos de guerra contra o País ou invadi-lo:","Pena - reclusão, de 3 (três) a 8 (oito) anos.","§ 1º Aumenta-se a pena de metade até o dobro, se declarada guerra em decorrência das condutas previstas no caput deste artigo.","§ 2º Se o agente participa de operação bélica com o fim de submeter o território nacional, ou parte dele, ao domínio ou à soberania de outro país:","Pena - reclusão, de 4 (quatro) a 12 (doze) anos. (Artigo acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)","Atentado à integridade nacional (Nome jurídico acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-J","law":"cp","ref":"359-J","label":"Código Penal — art. 359-J","paragraphs":["Art. 359-J. Praticar violência ou grave ameaça com a finalidade de desmembrar parte do território nacional para constituir país independente:","Pena - reclusão, de 2 (dois) a 6 (seis) anos, além da pena correspondente à violência. (Artigo acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)","Espionagem (Nome jurídico acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-K","law":"cp","ref":"359-K","label":"Código Penal — art. 359-K","paragraphs":["Art. 359-K. Entregar a governo estrangeiro, a seus agentes, ou a organização criminosa estrangeira, em desacordo com determinação legal ou regulamentar, documento ou informação classificados como secretos ou ultrassecretos nos termos da lei, cuja revelação possa colocar em perigo a preservação da ordem constitucional ou a soberania nacional:","Pena - reclusão, de 3 (três) a 12 (doze) anos.","§ 1º Incorre na mesma pena quem presta auxílio a espião, conhecendo essa circunstância, para subtraí-lo à ação da autoridade pública.","§ 2º Se o documento, dado ou informação é transmitido ou revelado com violação do dever de sigilo:","Pena - reclusão, de 6 (seis) a 15 (quinze) anos.","§ 3º Facilitar a prática de qualquer dos crimes previstos neste artigo mediante atribuição, fornecimento ou empréstimo de senha, ou de qualquer outra forma de acesso de pessoas não autorizadas a sistemas de informações:","Pena - detenção, de 1 (um) a 4 (quatro) anos.","§ 4º Não constitui crime a comunicação, a entrega ou a publicação de informações ou de documentos com o fim de expor a prática de crime ou a violação de direitos humanos. (Artigo acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-L","law":"cp","ref":"359-L","label":"Código Penal — art. 359-L","paragraphs":["Art. 359-L. Tentar, com emprego de violência ou grave ameaça, abolir o Estado Democrático de Direito, impedindo ou restringindo o exercício dos poderes constitucionais:","Pena - reclusão, de 4 (quatro) a 8 (oito) anos, além da pena correspondente à violência. (Artigo acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)","Golpe de Estado (Nome jurídico acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-M","law":"cp","ref":"359-M","label":"Código Penal — art. 359-M","paragraphs":["Art. 359-M. Tentar depor, por meio de violência ou grave ameaça, o governo legitimamente constituído:","Pena - reclusão, de 4 (quatro) a 12 (doze) anos, além da pena correspondente à violência. (Artigo acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)","Art. 359-M-A. Quando os delitos deste Capítulo estão inseridos no mesmo contexto, a pena deverá ser aplicada, ainda que existente desígnio autônomo, na forma do concurso formal próprio de que trata a primeira parte do art. 70, vedando-se a aplicação do cômputo cumulativo previsto na segunda parte desse dispositivo e no art. 69, todos deste Código. (Artigo acrescido pela Lei nº 15.402, de 8/5/2026)","Art. 359-M-B. Quando os crimes previstos neste Capítulo forem praticados em contexto de multidão, a pena será reduzida de 1/3 (um terço) a 2/3 (dois terços), desde que o agente não tenha praticado ato de financiamento ou exercido papel de liderança. (Artigo acrescido pela Lei nº 15.402, de 8/5/2026)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-N","law":"cp","ref":"359-N","label":"Código Penal — art. 359-N","paragraphs":["Art. 359-N. Impedir ou perturbar a eleição ou a aferição de seu resultado, mediante violação indevida de mecanismos de segurança do sistema eletrônico de votação estabelecido pela Justiça Eleitoral:","Pena - reclusão, de 3 (três) a 6 (seis) anos, e multa. (Artigo acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)","(VETADO na Lei nº 14.197, de 1º/9/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-O","law":"cp","ref":"359-O","label":"Código Penal — art. 359-O","paragraphs":["Art. 359-O. (VETADO na Lei nº 14.197, de 1º/9/2021)","Violência política (Nome jurídico acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-P","law":"cp","ref":"359-P","label":"Código Penal — art. 359-P","paragraphs":["Art. 359-P. Restringir, impedir ou dificultar, com emprego de violência física, sexual ou psicológica, o exercício de direitos políticos a qualquer pessoa em razão de seu sexo, raça, cor, etnia, religião ou procedência nacional:","Pena - reclusão, de 3 (três) a 6 (seis) anos, e multa, além da pena correspondente à violência. (Artigo acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)","(VETADO na Lei nº 14.197, de 1º/9/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-Q","law":"cp","ref":"359-Q","label":"Código Penal — art. 359-Q","paragraphs":["Art. 359-Q. (VETADO na Lei nº 14.197, de 1º/9/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-R","law":"cp","ref":"359-R","label":"Código Penal — art. 359-R","paragraphs":["Art. 359-R. Destruir ou inutilizar meios de comunicação ao público, estabelecimentos, instalações ou serviços destinados à defesa nacional, com o fim de abolir o Estado Democrático de Direito:","Pena - reclusão, de 2 (dois) a 8 (oito) anos. (Artigo acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-T","law":"cp","ref":"359-T","label":"Código Penal — art. 359-T","paragraphs":["Art. 359-T. Não constitui crime previsto neste Título a manifestação crítica aos poderes constitucionais nem a atividade jornalística ou a reivindicação de direitos e garantias constitucionais por meio de passeatas, de reuniões, de greves, de aglomerações ou de qualquer outra forma de manifestação política com propósitos sociais. (Artigo acrescido pela Lei nº 14.197, de 1º/9/2021, publicada no DOU de 2/9/2021, em vigor 90 dias após a publicação)","(VETADO na Lei nº 14.197, de 1º/9/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:359-U","law":"cp","ref":"359-U","label":"Código Penal — art. 359-U","paragraphs":["Art. 359-U. (VETADO na Lei nº 14.197, de 1º/9/2021)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"},{"key":"cp:30","law":"cp","ref":"30","label":"Código Penal — art. 30","paragraphs":["Art. 30. Não se comunicam as circunstâncias e as condições de caráter pessoal, salvo quando elementares do crime. (Artigo com redação dada pela Lei nº 7.209, de 11/7/1984)"],"url":"https://legis.senado.leg.br/norma/527942/publicacao/39870011"}];})(window);
